class Solution:
    def averageWaitingTime(self, customers: List[List[int]]) -> float:
        start = customers[0][0]
        end = start + customers[0][1]
        total_wait = end - start
        for c in customers[1:]:
            start = c[0]
            if start <= end:
                end += c[1]
                total_wait = total_wait + end - start
            else:
                end = c[0]+c[1]
                total_wait += c[1]
        return total_wait/len(customers)

class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        zero = binary.count('0') # count number of '0'
        zero_idx = binary.index('0') if zero > 0 else 0 # find the index of fist '0' if exists
        one = len(binary) - zero_idx - zero # count number of '1' (not including leading '1's)
        return f"{binary[:zero_idx]}{'1'*(zero-1)}{'0'*min(zero, 1)}{'1'*one}"

class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        result = list(binary)
        zeros = ones = 0
        for i, c in enumerate(result):
            if c == '0':
                zeros += 1
            elif zeros == 0:
                ones += 1
            result[i] = '1'
        if ones != len(result):
            result[zeros+ones-1] = '0'
        return "".join(result)
